(()=>{"use strict";(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,375,e=>{var i=e.i(43476),o=e.i(71645);let n={ko:(e,i)=>`Vibe Memory를 ${e}에 연결해줘. 다른 하네스 설정을 변환해서 쓰지 말고 ${i}의 제품 전용 가이드를 먼저 읽어. 현재 설치 상태와 버전을 확인하고 Skill, 원격 MCP, 자동 Hook을 각각 설명한 뒤 필요한 변경 diff와 권한 범위를 보여줘. 내가 검토하기 전에는 Hook이나 설정 파일을 수정하지 말고, 승인 후 설치\xb7웹 인증\xb7검증까지 진행해.`,en:(e,i)=>`Connect Vibe Memory to ${e}. Read the product-specific guide at ${i} first and do not reuse another harness's configuration. Inspect the current installation and version, explain Skill, remote MCP, and lifecycle Hooks separately, and show the exact diff and permission scope. Do not change Hook or configuration files before I review them. After approval, complete installation, web authorization, and verification.`,zh:(e,i)=>`请将 Vibe Memory 连接到 ${e}。先阅读 ${i} 的产品专用指南，不要转换或复用其他智能体框架的配置。检查当前安装状态和版本，分别说明 Skill、远程 MCP 与自动 Hook，并展示准确的差异和权限范围。在我审核前不要修改 Hook 或配置文件；批准后再完成安装、网页授权与验证。`,ja:(e,i)=>`Vibe Memoryを${e}に接続してください。別のハーネス設定を流用せず、まず${i}の製品別ガイドを読んでください。現在のインストール状態とバージョンを確認し、Skill・リモートMCP・自動Hookを個別に説明して、正確な差分と権限範囲を示してください。確認前にHookや設定ファイルを変更せず、承認後にインストール・Web認証・検証まで進めてください。`,es:(e,i)=>`Conecta Vibe Memory con ${e}. Lee primero la gu\xeda espec\xedfica de ${i} y no reutilices la configuraci\xf3n de otro agente. Revisa la instalaci\xf3n y la versi\xf3n actuales, explica por separado Skill, MCP remoto y Hooks autom\xe1ticos, y muestra el diff exacto y el alcance de permisos. No modifiques Hooks ni archivos de configuraci\xf3n antes de mi revisi\xf3n. Tras aprobarlo, completa la instalaci\xf3n, la autorizaci\xf3n web y la verificaci\xf3n.`,vi:(e,i)=>`Kết nối Vibe Memory với ${e}. Trước ti\xean h\xe3y đọc hướng dẫn ri\xeang tại ${i}, kh\xf4ng chuyển đổi cấu h\xecnh của harness kh\xe1c. Kiểm tra trạng th\xe1i c\xe0i đặt v\xe0 phi\xean bản, giải th\xedch ri\xeang Skill, MCP từ xa v\xe0 Hook tự động, rồi hiển thị diff ch\xednh x\xe1c c\xf9ng phạm vi quyền. Kh\xf4ng sửa Hook hoặc tệp cấu h\xecnh trước khi t\xf4i xem x\xe9t. Sau khi ph\xea duyệt, ho\xe0n tất c\xe0i đặt, x\xe1c thực web v\xe0 kiểm tra.`,th:(e,i)=>`เชื่อม Vibe Memory กับ ${e} โดยอ่านคู่มือเฉพาะผลิตภัณฑ์ที่ ${i} ก่อน และอย่านำการตั้งค่าของ harness อื่นมาแปลงใช้ ตรวจสอบสถานะการติดตั้งและเวอร์ชัน อธิบาย Skill, MCP ระยะไกล และ Hook อัตโนมัติแยกกัน พร้อมแสดง diff และขอบเขตสิทธิ์ที่แน่นอน ห้ามแก้ Hook หรือไฟล์ตั้งค่าก่อนที่ฉันจะตรวจสอบ หลังอนุมัติแล้วจึงติดตั้ง ยืนยันผ่านเว็บ และตรวจสอบให้เสร็จ`};function t({name:e}){return(0,i.jsx)("svg",{className:"svg-icon","aria-hidden":"true",children:(0,i.jsx)("use",{href:`/assets/icons.svg#${e}`})})}e.s(["HarnessGuideActions",0,function({name:e,slug:a}){let[r,s]=(0,o.useState)(!1);async function c(){let i=window.vmCurrentLocale?.()||"ko",o=`https://vibememory.io/guide/${a}`;await navigator.clipboard.writeText(n[i](e,o)),s(!0),window.setTimeout(()=>s(!1),1800)}return(0,i.jsxs)("div",{className:"harness-hero-actions",children:[(0,i.jsxs)("button",{className:"button primary",type:"button",onClick:c,children:[(0,i.jsx)(t,{name:r?"check":"copy"}),r?"설치 프롬프트를 복사했습니다":"제품별 설치 프롬프트 복사"]}),(0,i.jsxs)("a",{className:"button button-outline",href:"/downloads/vibe-memory-skill.zip",download:!0,children:[(0,i.jsx)(t,{name:"download"})," Skill 내려받기"]})]})}])},58055,e=>{var i=e.i(71645);e.s(["PublicHeaderControls",0,function(){return(0,i.useEffect)(()=>{window.vmMountLanguageSwitcher?.(),window.vmTheme?.mount?.()},[]),null}])}])})();